def _cross_entropy_from_histogram(
    hist: np.ndarray, bin_centers: np.ndarray, threshold: float
) -> float:
    """Calculate the Li cross entropy of a split from a precomputed histogram."""
    above_threshold = np.flatnonzero(bin_centers > threshold)
    if above_threshold.size == 0:
        return float(np.inf)
    t = int(above_threshold[0])
    m0a = np.sum(hist[:t])  # 0th moment, background
    m0b = np.sum(hist[t:])
    if m0a == 0 or m0b == 0:
        return float(np.inf)
    m1a = np.sum(hist[:t] * bin_centers[:t])  # 1st moment, background
    m1b = np.sum(hist[t:] * bin_centers[t:])
    mua = m1a / m0a  # mean value, background
    mub = m1b / m0b
    if mua <= 0 or mub <= 0:
        return float(np.inf)
    nu = -m1a * np.log(mua) - m1b * np.log(mub)
    return float(nu)

